import { Component } from '@angular/core';
import { ButtonComponent } from "../../../../shared/components/button/button.component";
import { BlogCardComponent } from "../../../../shared/components/cards/blog-card/blog-card.component";

@Component({
  selector: 'app-blogs',
  imports: [ButtonComponent, BlogCardComponent],
  templateUrl: './blogs.component.html',
  styleUrl: './blogs.component.css'
})
export class BlogsComponent {

  displayText() : void{
    console.log("Button clicked.")
  }
}
<section class="bg-white py-16">
    <div class="container mx-auto">
        <header class="flex items-center justify-between">
            <h1 class="text-3xl font-medium">Recipe <span class="text-primary">Blogs</span></h1>
            <div>
                <app-button  label="View blogs" [class]="'text-sm font-semibold bg-primary px-4 rounded-full text-pretty text-center py-2 text-white'"></app-button>
            </div>
        </header>
        <div class="cards_wrapper mt-12 flex items-center-center gap-5 ">
            <app-blog-card src="assets/images/blogs-img/blog-1.jpg"></app-blog-card>
            <app-blog-card src="assets/images/blogs-img/blog-2.jpg"></app-blog-card>
            <app-blog-card src="assets/images/blogs-img/blog-3.jpg"></app-blog-card>
            <app-blog-card src="assets/images/blogs-img/blog-4.jpg"></app-blog-card>
        </div>
    </div>
</section>
